// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the one box of the Alt+I inline chat, wherever it shows: the robot, the input, the
//          status text, and its look (the styles are added to the page by the first box made).
//          Used under a code editor (inline_edit.jsx) and over the Terminal (terminal.py's page,
//          which gets this file from the backend: GET /inline_box.js). Where the box sits is
//          the user's (app.css `.cm-panels .inline-box`, the Terminal page's `#ask`).
// Usage: const box = inlineBox({ placeholder, hint }); parent.append(box.dom);
//        box.say("Thinking…"); box.thinking(true); box.say("failed", "error");
// ---------------------------------------------------------------------------

// The AI's icon is .ai-icon (sparkles, a Nerd Font glyph in a box its own size): the rule below is a copy of the one in
// assets/app.css (render.ai_icon), for the Terminal's page, which has no app.css.

// Everforest, as assets/app.css: its variables where the page has them (the app), else the
// same colours written out (the Terminal's page has no app.css)
const CSS = `
.inline-box { display: flex; align-items: center; gap: 8px; padding: 5px 9px; background: var(--bg1, #343f44);
  border: 1px solid var(--green, #a7c080); border-radius: 6px; font: 13px var(--sans, sans-serif);
  color: var(--fg, #d3c6aa); box-shadow: 0 4px 14px rgba(0, 0, 0, .35); }
.inline-box[hidden] { display: none; }
.ai-icon { display: inline-block; flex: none; width: 0.915em; height: 1em; font: 12.5px/1 var(--mono, "JetBrainsMono Nerd Font", "JetBrainsMono NF", monospace);
  text-align: left; text-indent: 0; white-space: nowrap; vertical-align: -0.12em; }
.ai-icon::before { content: "\\F0674"; }
.inline-box-icon { color: var(--green, #a7c080); }
.inline-box-input { flex: 1; min-width: 120px; background: none; border: 0; outline: 0; color: inherit; font: inherit; }
.inline-box-input:disabled { opacity: .6; }
.inline-box-status { color: var(--grey1, #859289); font-size: 12px; max-width: 60%; }
.inline-box-status.is-error { color: var(--red, #e67e80); }
.inline-box-status.is-note { color: var(--fg, #d3c6aa); }
/* while the AI is thinking: the icon and the status text pulse */
@keyframes inline-box-pulse { 50% { opacity: .45; } }
.inline-box.is-thinking .inline-box-icon { color: var(--purple, #d699b6); animation: inline-box-pulse 1.1s ease-in-out infinite; }
.inline-box.is-thinking .inline-box-status { color: var(--fg, #d3c6aa); animation: inline-box-pulse 1.1s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) {
  .inline-box.is-thinking .inline-box-icon, .inline-box.is-thinking .inline-box-status { animation: none; }
}
`;

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  node.className = className;
  if (text) node.textContent = text;
  return node;
};

/** A box, not yet in the page: { dom, input, status, say(text, kind), thinking(on) }.
 *  hint: the status text it starts with. kind: "" (grey), "note" or "error". */
export function inlineBox({ placeholder, hint }) {
  if (!document.getElementById("inline-box-style")) {
    const style = el("style", "", CSS);
    style.id = "inline-box-style";
    document.head.append(style);
  }
  const dom = el("div", "inline-box");
  const input = el("input", "inline-box-input");
  input.placeholder = placeholder;
  input.spellcheck = false;
  input.autocomplete = "off";
  const status = el("span", "inline-box-status", hint);
  dom.append(el("span", "inline-box-icon ai-icon", ""), input, status);
  return {
    dom,
    input,
    status,
    say(text, kind) {
      status.textContent = text;
      status.className = `inline-box-status${kind ? ` is-${kind}` : ""}`;
    },
    thinking(on) {
      dom.classList.toggle("is-thinking", on);
    },
  };
}
